  [1213886] = { "$D1の間、魔法の呪文と効果による回復量を最大$N1、ダメージを最大$N2増加させ、マナの回復量を5秒ごとに$N3増加させます。フラスコの効果は一度に一つしか得られません。この効果は死亡しても持続します。", "治療量が$N1増加しています。\n呪文ダメージが$N2増加しています。\n$N4秒ごとにマナを$N3回復しています。", 0xc56ee57b, 0x325db2fe, "uu" },
  [1213892] = { "$D1の間、魔法の呪文と効果によるダメージを最大$N1増加させます。一度に効果を得られるフラスコは1つだけです。この効果は死亡しても持続します。", "呪文ダメージが$N1増加しています。", 0x866d214b, 0x62db0716, "uu" },
  [1213894] = { "Chain Healの詠唱時間を$D1短縮します。", nil, 0x7b104225, nil, "um" },
