  [1213900] = { "Lightning Bolt、Chain Lightning、Lava Burstの詠唱中にダメージによる中断を$N1%の確率で防ぎ、Elemental Focusのタレントが発動する確率が$N2%増加します。", nil, 0xcfd99980, nil, "um" },
  [1213901] = { "$D1の間、スタミナを$N1、防御値を$N2増加させます。フラスコの効果は一度に一つしか得られません。この効果は死亡しても持続します。", "スタミナが$N1増加しています。\nDefenseが$N2上昇しています。", 0x678ed333, 0xa407e17a, "uu" },
  [1213902] = { "Fire、Frost、Nature呪文のクリティカルダメージボーナスを$N1%増加させます。", nil, 0x21a58392, nil, "um" },
  [1213904] = { "$D1の間、敏捷性を$N1、クリティカル率を$N2%、Nature Resistanceを$N3上昇させます。", "敏捷性が$N1増加しています。\nクリティカル率が$N2%上昇しています。\nNature Resistanceが$N3上昇しています。", 0x71e89706, 0x94c24bd2, "uu" },
