  [1213922] = { "$D1の間、プレイヤーの走る速度を$N1%上昇させます。", "走る速度が$N1上昇しています。", 0xbd3f1cfa, 0xc6b86931, "uu" },
  [1213924] = { "爆発範囲内の者からマナを$N1吸い取り、吸い取ったマナの50%を対象へのダメージとして与えます。さらに爆発範囲内の対象を$D1の間、Silenceにします。", "沈黙させられています。", 0xecefecaa, 0x20816e34, "uu" },
